INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(11101, '2 Chronicles 31:18', '2 Chronicles', 31, 18, '&nbsp;د خپلو ښځو، بچو او خپلو نورو کشرانو سره د هغوئ ټولو نومونه ليکلے شوى وُو، ځکه چې هغوئ ته وئيلى شوى وُو چې هغوئ دې د خپلو مقدسو ذمه وارو ادا کولو دپاره هر وخت تيار اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11102, '2 Chronicles 31:19', '2 Chronicles', 31, 19, '&nbsp;کوم اِمامان چې په هغه ښارونو کښې اوسېدل چې د هارون اولاد ته حواله شوى وُو، يا چې د څرن په هغه زمکو کښې اوسېدل چې د دې ښارونو وې، نو هلته يو څو ذمه وار سړى داسې وُو چې هغوئ به د اِمامانو په کورَنو کښې په ټولو ناريناؤ باندې خوراک تقسيمولو او په هغه هر چا باندې يې هم خوراک تقسيمولو چې د چا نومونه د ليويانو په ډلو کښې ليکلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11103, '2 Chronicles 31:20', '2 Chronicles', 31, 20, '&nbsp;په ټوله يهوداه کښې، حزقياه بادشاه هغه څۀ کول چې څۀ صحيح وُو او چې په څۀ باندې مالِک خُدائ د هغۀ خُدائ پاک رضا کېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11104, '2 Chronicles 31:21', '2 Chronicles', 31, 21, '&nbsp;هغۀ د مالِک خُدائ د کور دپاره او د شريعت منلو دپاره چې هر څۀ هم کړى وُو، دا يې د زړۀ د اخلاصه کړى وُو او د خُدائ پاک طلبګار وو نو په دې وجه هغه کامياب وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11105, '2 Chronicles 32:1', '2 Chronicles', 32, 1, '&nbsp;د دې واقعو نه پس، چې په کومو کښې حزقياه بادشاه په وفادارۍ سره د مالِک خُدائ خِدمت کړے وو، د اسور بادشاه سينحرب په يهوداه حمله وکړه. هغۀ د پَخو دېوالونو ښارونه محاصره کړل او خپل لښکر له يې حُکم ورکړو چې دېوالونه راوغورزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11106, '2 Chronicles 32:2', '2 Chronicles', 32, 2, '&nbsp;کله چې حزقياه ته پته ولګېده چې سينحرب په يروشلم د حملې کولو اراده لرى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11107, '2 Chronicles 32:5', '2 Chronicles', 32, 5, '&nbsp;بادشاه د ښار دِفاع داسې مضبوطه کړه چې د دې دېوال يې مرمت کړل، په دې باندې يې برجونه جوړ کړل او بهرنى دېوال يې ورله جوړ کړو. د دې نه علاوه، هغۀ د دِفاع هغه ځايونه هم مرمت کړل چې په هغه زمکه باندې جوړ وُو چې د يروشلم د زړې برخې نمرخاتۀ طرف ته ډک کړے شوى وُو. هغۀ ډېره زياته وسله او ډالونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11108, '2 Chronicles 32:6', '2 Chronicles', 32, 6, '&nbsp;هغۀ په خلقو باندې فوجى آفسران مقرر کړل او هغوئ له يې حُکم ورکړو چې د ښار د دروازې سره په کولاو ځائ کښې راغونډ شئ. هغۀ ورته ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11109, '2 Chronicles 32:7', '2 Chronicles', 32, 7, '&nbsp;”تکړه شئ او حوصله مضبوطه کړئ او د اسور بادشاه نه او د هغه لښکر نه مۀ يرېږئ چې هغۀ راروان کړے دے. کوم ذات چې زمونږ مل دے نو هغه د هغۀ نه زيات طاقتور دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11110, '2 Chronicles 32:8', '2 Chronicles', 32, 8, '&nbsp;د هغۀ سره انسانى طاقت دے، خو مونږ سره د مالِک خُدائ زمونږ خُدائ پاک شته چې زمونږ مدد وکړى او زمونږ جنګونه وکړى.“ د خلقو د خپل بادشاه په دې خبره باندې حوصله مضبوطه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11111, '2 Chronicles 32:9', '2 Chronicles', 32, 9, '&nbsp;څۀ موده وروستو، کله چې سينحرب او د هغۀ لښکر تر اوسه پورې په لکيس کښې وو، نو هغۀ حزقياه او د يهوداه هغه خلقو ته چې د هغۀ سره په يروشلم کښې وُو دا پېغام ورولېږلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11112, '2 Chronicles 32:10', '2 Chronicles', 32, 10, '&nbsp;”زۀ د اسور بادشاه سينحرب دا وايم چې ستاسو په زړۀ کښې څۀ دى چې تاسو به د يروشلم محاصرې ته ټينګ شئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11113, '2 Chronicles 32:11', '2 Chronicles', 32, 11, '&nbsp;حزقياه تاسو ته وائى چې مالِک خُدائ ستاسو خُدائ پاک به تاسو زمونږ د طاقت نه بچ کړى، خو حزقياه تاسو دوکه کوى او دې ته به مو جوړوى چې د لوږې او تندې نه مړۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11114, '2 Chronicles 32:12', '2 Chronicles', 32, 12, '&nbsp;دا هغه کس دے چا چې د مالِک خُدائ علاقائى عبادتخانې او قربان‌ګاه تباه کړى دى او بيا يې د يهوداه او يروشلم خلقو ته ووئيل چې صِرف په يوه قربان‌ګاه باندې عبادت وکړئ او خوشبويۍ سوزوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11115, '2 Chronicles 32:13', '2 Chronicles', 32, 13, '&nbsp;تاسو ته پته نشته څۀ چې ما او زما پلار نيکۀ د نورو قومونو په خلقو باندې څۀ کړى دى؟ د بل يو قوم معبودانو خپل خلق د اسور بادشاه نه بچ کړى دى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11116, '2 Chronicles 32:14', '2 Chronicles', 32, 14, '&nbsp;د هغه ټولو مُلکونو يو خُدائ کله هم خپل مُلک زمونږ نه بچ کړے دے څۀ؟ نو بيا تاسو ولې وايئ چې ستاسو خُدائ تاسو بچ کولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11117, '2 Chronicles 32:15', '2 Chronicles', 32, 15, '&nbsp;نو حزقياه دې ته مۀ پرېږدئ چې دوکه مو کړى يا چې په داسې غلطه لار مو بوځى. په هغۀ باندې اعتبار مۀ کوئ. د يو قوم خُدائ هم خپل خلق د اسور د يو بادشاه نه نۀ دى بچ کړى. نو بې‌شکه ستاسو دا خُدائ هم تاسو نۀ شى بچ کولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11118, '2 Chronicles 32:16', '2 Chronicles', 32, 16, '&nbsp;د اسور آفسرانو د مالِک خُدائ، خُدائ پاک او د مالِک خُدائ خِدمت کوونکى حزقياه په حقله د دې نه هم زيات بدرد ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11119, '2 Chronicles 32:17', '2 Chronicles', 32, 17, '&nbsp;بادشاه چې کوم خط ليکلے وو دې خط په مالِک خُدائ د بنى اِسرائيلو په خُدائ پاک پورې ټوقې وکړې. په دې کښې ليکلى وُو، ”د قومونو خُدايانو خپل خلق زما د طاقت نه نۀ دى بچ کړى او نۀ به د حزقياه خُدائ خپل خلق زما نه بچ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11120, '2 Chronicles 32:18', '2 Chronicles', 32, 18, '&nbsp;آفسرانو په عبرانۍ کښې د دې دپاره چغې ووهلې چې د يروشلم هغه خلق ويروى او بې‌حوصلې يې کړى کوم چې د ښار په دېوال باندې وُو، نو داسې د ښار قبضه کول به آسان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11121, '2 Chronicles 32:19', '2 Chronicles', 32, 19, '&nbsp;هغوئ د يروشلم د خُدائ پاک په حقله هم هغه شان خبرې وکړې چې د نورو خلقو د خُدايانو په حقله يې کولې، د هغه بُتانو چې د انسان لاسونو جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11122, '2 Chronicles 32:20', '2 Chronicles', 32, 20, '&nbsp;حزقياه بادشاه او د آموص زوئ يشعياه پېغمبر خُدائ پاک ته سوال وکړو او هغۀ ته يې د مدد دپاره فرياد وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11123, '2 Chronicles 32:21', '2 Chronicles', 32, 21, '&nbsp;مالِک خُدائ يوه فرښته راولېږله چې هغې د اسور د لښکر فوجيان او آفسران ووژل. نو داسې بادشاه اسور ته واپس شرمېدلے لاړو. يوه ورځ چې کله هغه د خپل خُدائ په عبادتخانه کښې وو، نو د هغۀ يو څو زامنو هغه په تُورو باندې ووهلو او مړ يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11124, '2 Chronicles 32:22', '2 Chronicles', 32, 22, '&nbsp;نو داسې مالِک خُدائ حزقياه بادشاه او د يروشلم خلق د اسور بادشاه سينحرب د زور نه او د هغوئ د نورو دشمنانو نه بچ کړل. او هغوئ د هر يو قوم سره په امن کښې ژوند تېرولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11125, '2 Chronicles 32:23', '2 Chronicles', 32, 23, '&nbsp;ډېر خلق يروشلم ته راتلل، چې مالِک خُدائ له يې نذرانې او حزقياه له يې تُحفې راوړې، نو د هغه وخت نه حزقياه د ټولو قومونو په نظر کښې عزتمند وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11126, '2 Chronicles 32:24', '2 Chronicles', 32, 24, '&nbsp;تقريباً هم هغه وخت حزقياه بادشاه بيمار شو او مرګ ته نزدې وو. هغۀ دُعا وکړه او مالِک خُدائ ورته يوه نښه وښودله چې هغه به روغ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11127, '2 Chronicles 32:25', '2 Chronicles', 32, 25, '&nbsp;خو حزقياه ډېر زيات مغروره وو او د هغه څۀ شکريه يې ادا نۀ کړه چې مالِک خُدائ د هغۀ دپاره کړى وُو، نو په دې وجه د مالِک خُدائ غصه په هغۀ، په يهوداه او يروشلم نازله شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11128, '2 Chronicles 32:26', '2 Chronicles', 32, 26, '&nbsp;خو په آخر کښې حزقياه او د يروشلم خلقو خپل ځانونه عاجز کړل، نو ځکه مالِک خُدائ د حزقياه په ژوند کښې خلقو له سزا ورنۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11129, '2 Chronicles 32:27', '2 Chronicles', 32, 27, '&nbsp;حزقياه بادشاه ډېر مالداره شو او هر چا به د هغۀ عزت کولو. هغۀ د خپلو سرو زرو، سپينو زرو، قيمتى کاڼو، مصالحو، ډالونو او د نورو قيمتى څيزونو دپاره ګودامونه جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11130, '2 Chronicles 32:28', '2 Chronicles', 32, 28, '&nbsp;د دې نه علاوه، هغۀ د خپلې غلې، ميو، زيتُونو تېلو دپاره ګودامونه، د څاروو دپاره ديرې او د ګډو دپاره شپولونه جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11131, '2 Chronicles 32:29', '2 Chronicles', 32, 29, '&nbsp;د دې هر څۀ نه علاوه، خُدائ پاک هغۀ له ګډې او څاروى ورکړى وُو او نور دولت يې دومره ډېر ورکړے وو چې هغۀ ډېر ښارونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11132, '2 Chronicles 32:30', '2 Chronicles', 32, 30, '&nbsp;دا حزقياه بادشاه وو چې هغۀ د جيحون د چينو خولې بندې کړې او اوبو له يې يوه لار جوړه کړه چې اوبۀ د يو سورنګ په ذريعه د يروشلم په دېوالونو کښې دننه يو ځائ ته بهيږى. حزقياه چې هر کار کولو نو په هغې کښې کاميابېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11133, '2 Chronicles 32:31', '2 Chronicles', 32, 31, '&nbsp;او چې کله د بابل سفير د هغه عجيبه واقعې د معلومولو دپاره راغلو چې کومه په هغه مُلک کښې شوې وه، نو خُدائ پاک حزقياه د دې دپاره يواځې پرېښودو چې د هغۀ نېت معلوم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11134, '2 Chronicles 32:32', '2 Chronicles', 32, 32, '&nbsp;حزقياه بادشاه چې نور هر څۀ کړى وُو سره د هغۀ د نېکو عملونو، دا د آموص زوئ يشعياه پېغمبر په رويا کښې ليکلے شوى دى چې هغه د يهوداه او اِسرائيل د بادشاهانو د تاريخ يوه حِصه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11135, '2 Chronicles 32:33', '2 Chronicles', 32, 33, '&nbsp;نو حزقياه مړ شو او هغه د شاهى اديرې په پاسنۍ حِصه کښې ښخ شو. د هغۀ په مرګ باندې د يهوداه او يروشلم ټولو خلقو هغۀ له يو لوئ عزت ورکړو. د هغۀ زوئ منسى د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11136, '2 Chronicles 33:1', '2 Chronicles', 33, 1, '&nbsp;منسى دولس کلن وو چې هغه د يهوداه بادشاه جوړ شو او په يروشلم يې پينځۀ پنځوس کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11137, '2 Chronicles 33:2', '2 Chronicles', 33, 2, '&nbsp;منسى د هغه قومونو هغه حرام کارونه کول کوم چې د مالِک خُدائ په نظر کښې بد وُو. دا هم هغه خلق وُو کوم چې مالِک خُدائ په هغه وخت کښې د هغه مُلک نه ويستلى وُو چې کله د هغۀ خلق مخ په وړاندې تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11138, '2 Chronicles 33:3', '2 Chronicles', 33, 3, '&nbsp;هغۀ علاقائى عبادتخانې بيا جوړې کړې چې کوم د هغۀ پلار حزقياه تباه کړى وُو. هغۀ د بعل د عبادت دپاره قربان‌ګاه جوړې کړې، د اشيرې بُت نښې يې جوړې کړې او د ستورو عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11139, '2 Chronicles 33:4', '2 Chronicles', 33, 4, '&nbsp;هغۀ د مالِک خُدائ په کور کښې د غېرو قومونو قربان‌ګاه جوړې کړې، د کوم ځائ په حقله چې مالِک خُدائ فرمائيلى وُو چې، ”زما نوم به په يروشلم کښې د همېشه دپاره پاتې شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11140, '2 Chronicles 33:5', '2 Chronicles', 33, 5, '&nbsp;د مالِک خُدائ د کور په دوو دربارونو کښې هغۀ د ستورو د عبادت دپاره قربان‌ګاه جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11141, '2 Chronicles 33:6', '2 Chronicles', 33, 6, '&nbsp;هغۀ د هنوم په وادۍ کښې خپل زامن د سوزېدونکې نذرانو په توګه قربانى کړل. هغۀ د غېبو کارونو او جادو نه کار اخستلو او قسمت ښودونکو او د فالګرو سره يې مشورې وکړې. هغۀ د مالِک خُدائ خِلاف لويه ګناه وکړه او د هغۀ غصه يې راوپاروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11142, '2 Chronicles 33:7', '2 Chronicles', 33, 7, '&nbsp;هغۀ چې کوم بُت جوړ کړے وو هغه يې واخستلو او د خُدائ پاک په کور کښې يې ودرولو چې د کوم په حقله خُدائ پاک داؤد او د هغۀ زوئ سليمان ته فرمائيلى وُو، ”په دې کور کښې او په يروشلم کښې به زۀ خپل نوم د همېشه دپاره وساتم کوم ښار چې ما د بنى اِسرائيلو د ټولو قبيلو نه خوښ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11143, '2 Chronicles 33:8', '2 Chronicles', 33, 8, '&nbsp;کۀ بنى اِسرائيليان زما ټول حُکمونه منى او هغه ټول قانون پوره کوى چې زما خِدمت کوونکى موسىٰ هغوئ له ورکړے دے، نو زۀ به هغوئ نۀ پرېږدم چې د هغه مُلک نه وويستلے شى چې کوم ما د هغوئ پلار نيکۀ له ورکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11144, '2 Chronicles 33:9', '2 Chronicles', 33, 9, '&nbsp;خو منسى د يهوداه او يروشلم خلق بې‌لارې کړل او هغوئ د هغه قومونو نه هم لوئې ګناهونه وکړل کوم چې مالِک خُدائ تباه کړى وُو کله چې بنى اِسرائيليان مخ په وړاندې تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11145, '2 Chronicles 33:10', '2 Chronicles', 33, 10, '&nbsp;اګر چې مالِک خُدائ منسى او د هغۀ خلقو له خبردارے ورکړو، خو هغوئ به ورته غوږ نۀ نيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11146, '2 Chronicles 33:11', '2 Chronicles', 33, 11, '&nbsp;نو مالِک خُدائ د اسور فوجى مشران ولېږل چې په يهوداه باندې حمله وکړى. او هغوئ منسى ونيولو، کُنډې يې ورته واچولې او په زنځيرونو باندې يې وتړلو او بابل ته يې بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11147, '2 Chronicles 33:12', '2 Chronicles', 33, 12, '&nbsp;هغه د خپلو مصيبتونو په وجه عاجز شو او مالِک خُدائ، خُدائ پاک ته راوګرځېدو او هغۀ ته يې د مدد دپاره سوال وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11148, '2 Chronicles 33:13', '2 Chronicles', 33, 13, '&nbsp;خُدائ پاک د منسى سوال واورېدو او قبول يې کړو او هغه يې ولېږلو چې يروشلم ته واپس لاړ شى او بيا حکومت وکړى. نو منسى ته پته ولګېده چې مالِک خُدائ په رښتيا خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11149, '2 Chronicles 33:14', '2 Chronicles', 33, 14, '&nbsp;د دې نه پس، منسى د داؤد ښار د بهرنى دېوال اوچتوالے زيات کړو، د نمرپرېواتۀ په طرف په وادۍ کښې د جيحون د چشمې نه د کبانو دروازې پورې او هم دغه دېوال د عوفل د غر نه هم راتاو وو. هغۀ د يهوداه د پَخو دېوالونو په هر يو ښار کښې يو يو فوجى آفسر مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11150, '2 Chronicles 33:15', '2 Chronicles', 33, 15, '&nbsp;هغۀ د مالِک خُدائ د کور نه هغه پردى بُتان او نښې لرې کړې کومې چې هغۀ هلته اېښې وې او هغۀ د غېرو قومونو هغه قربان‌ګاه لرې کړې کومې چې د مالِک خُدائ د کور په غرۀ او په يروشلم کښې په نورو ځايونو کښې وې، هغۀ دا ټول څيزونه د ښار نه بهر يوړل او وې غورزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11151, '2 Chronicles 33:16', '2 Chronicles', 33, 16, '&nbsp;هغۀ هغه قربان‌ګاه هم مرمت کړه چرته چې د مالِک خُدائ عبادت کېدو او چې هغۀ ورباندې د سلامتۍ نذرانې او د شکرانې نذرانې پېش کولې. هغۀ د يهوداه ټولو خلقو له حُکم ورکړو چې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک عبادت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11152, '2 Chronicles 33:17', '2 Chronicles', 33, 17, '&nbsp;اګر چې خلقو په علاقائى عبادتخانو کښې هم قربانۍ پېش کولې، خو هغوئ دا صِرف مالِک خُدائ ته پېش کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11153, '2 Chronicles 33:18', '2 Chronicles', 33, 18, '&nbsp;نور هر څۀ چې منسى کړى وُو، هغۀ چې خُدائ پاک ته کوم سوال کړے وو او د پېغمبرانو هغه پېغامونه چې هغوئ د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک په نوم د هغۀ سره خبرې وکړې، دا هر څۀ د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11154, '2 Chronicles 33:19', '2 Chronicles', 33, 19, '&nbsp;د بادشاه دُعا او د خُدائ پاک د دُعا قبلول او د هغۀ د توبې نه مخکښې د هغه ګناهونو حِساب کِتاب چې هغۀ کړى وُو، هغه بد عملونه چې هغۀ کړى وُو، علاقائى عبادتخانې او د اشيرې بُت کومې نښې چې هغۀ جوړې کړې وې او هغه بُتان چې هغۀ يې عبادت کولو، دا هر څۀ د پېغمبرانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11155, '2 Chronicles 33:20', '2 Chronicles', 33, 20, '&nbsp;منسى مړ شو او په محل کښې ښخ شو او د هغۀ زوئ امون د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11156, '2 Chronicles 33:21', '2 Chronicles', 33, 21, '&nbsp;امون دوويشت کلن وو چې هغه د يهوداه بادشاه جوړ شو او هغۀ په يروشلم باندې دوه کاله حکومت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11157, '2 Chronicles 33:22', '2 Chronicles', 33, 22, '&nbsp;د خپل پلار منسى په شان هغۀ هم د مالِک خُدائ خِلاف ګناه وکړه او چې د هغۀ پلار د کومو بُتانو عبادت کړے وو نو هغۀ يې هم عبادت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11158, '2 Chronicles 33:23', '2 Chronicles', 33, 23, '&nbsp;خو هغه د خپل پلار په شان عاجز نۀ شو او نۀ مالِک خُدائ ته راوګرځېدو، هغه د خپل پلار نه هم زيات ګناهګار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11159, '2 Chronicles 33:24', '2 Chronicles', 33, 24, '&nbsp;د امون آفسرانو د هغۀ خِلاف منصوبه جوړه کړه او په محل کښې يې ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11160, '2 Chronicles 33:25', '2 Chronicles', 33, 25, '&nbsp;د يهوداه خلقو د امون قاتِلان ووژل او د هغۀ زوئ يوسياه يې بادشاه جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11161, '2 Chronicles 34:1', '2 Chronicles', 34, 1, '&nbsp;يوسياه اتۀ کلن وو چې هغه بادشاه جوړ شو او يو دېرش کاله يې په يروشلم بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11162, '2 Chronicles 34:2', '2 Chronicles', 34, 2, '&nbsp;هغۀ هم هغه کار کولو چې په څۀ باندې مالِک خُدائ خوشحالېدو، هغه د خپل پلار نيکۀ داؤد په نقش قدم باندې روان وو او هغه د خُدائ پاک د قانون نه اخوا دېخوا نۀ اوړېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11163, '2 Chronicles 34:3', '2 Chronicles', 34, 3, '&nbsp;د يوسياه د بادشاهۍ په اتم کال، چې په کوم وخت کښې هغه لا وړوکے وو، نو هغۀ د خپل پلار نيکۀ داؤد خُدائ پاک عبادت شروع کړو. څلور کاله وروستو هغۀ علاقائى عبادتخانې، د اشيرې بُت نښې او د نورو ټولو بُتانو تباه کول شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11164, '2 Chronicles 34:4', '2 Chronicles', 34, 4, '&nbsp;د هغۀ د ښودنې لاندې هغه قربان‌ګاه ټوټې ټوټې کړے شوه چرته چې د بعل عبادت کېدو او د دې سره نزدې د خوشبويۍ قربان‌ګاه راوغورزولے شوې. هغوئ د اشيرې بُتانو او د نورو ټولو بُتانو نه خاورې جوړې کړې او هغه خاورې يې د هغه خلقو په قبرونو باندې وشيندلې چا چې دې ته قربانۍ پېش کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11165, '2 Chronicles 34:5', '2 Chronicles', 34, 5, '&nbsp;هغۀ د بُت پرستو اِمامانو هډُوکى په هغه قربان‌ګاه باندې وسوزول چرته چې هغوئ عبادت کړے وو. د دې هر څۀ کولو په وجه هغۀ يهوداه او يروشلم بيا پاک کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11166, '2 Chronicles 34:6', '2 Chronicles', 34, 6, '&nbsp;هغۀ په ښارونو کښې او د منسى، اِفرائيم او شمعون او په شمال کښې د نفتالى پورې هم دغه شان کار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11167, '2 Chronicles 34:7', '2 Chronicles', 34, 7, '&nbsp;د شمالى بادشاهۍ په ټوله علاقه کښې هغۀ قربان‌ګاه او د اشيرې بُت نښې ټوټې ټوټې کړې او بُتان يې خاورې کړل او د خوشبويۍ ټولې قربان‌ګاه يې ټوټې ټوټې کړې. بيا هغه يروشلم ته راواپس شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11168, '2 Chronicles 34:8', '2 Chronicles', 34, 8, '&nbsp;د هغۀ د بادشاهۍ په اتلسم کال، د هغې نه پس چې کله هغۀ د غېرو قومونو د عبادت نه مالِک خُدائ کور او هغه مُلک پاک کړے وو، نو يوسياه بادشاه دا درې سړى ولېږل چې د مالِک خُدائ، خُدائ پاک کور مرمت کړى، د اصلياه زوئ سافن، معسياه، چې د يروشلم حکمران وو او د يهوآخز زوئ يوآخ چې مشر آفسر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11169, '2 Chronicles 34:9', '2 Chronicles', 34, 9, '&nbsp;کومې پېسې چې ليوى خادمانو د مالِک خُدائ کور کښې راغونډې کړې وې هغه يې مشر اِمام خِلقياه له ورکړې. دا د اِفرائيم او منسى او د شمالى ټولې بادشاهۍ نه او د يهوداه، بنيامين او د يروشلم د خلقو نه راغونډې شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11170, '2 Chronicles 34:10', '2 Chronicles', 34, 10, '&nbsp;بيا دا پېسې هغه درېو سړو ته حواله شوې چې د مالِک خُدائ د کور د مرمت مشران وُو او هغوئ دا پېسې دې مزدورانو له ورکړې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11171, '2 Chronicles 34:11', '2 Chronicles', 34, 11, '&nbsp;يعنې ترکاڼانو او ګِلکارانو له چې جوړ شوى کاڼى او لرګى واخلى او د هغه عمارت په مرمت کښې استعمال شى چې د يهوداه بادشاهانو پرېښے وو چې خراب شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11172, '2 Chronicles 34:12', '2 Chronicles', 34, 12, '&nbsp;کومو خلقو چې دا کار کولو هغه ټول محنتى وُو. د هغوئ مشرى دې څلورو ليويانو کوله، د مرارى د قبيلې يحت او عبدياه او د قُهات د قبيلې زکرياه او مسلام. ليويان تکړه موسيقاران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11173, '2 Chronicles 34:13', '2 Chronicles', 34, 13, '&nbsp;نور ليويان د سامان د وړلو راوړلو او د مختلفو کارونو د کاريګرو مشران وُو او نورو به حِساب کِتاب ساتلو او څوکيدارى به يې کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11174, '2 Chronicles 34:14', '2 Chronicles', 34, 14, '&nbsp;کله چې د ګودام نه پېسې ويستلے شوې نو په دې دوران کښې خِلقياه د مالِک خُدائ د شريعت کِتاب وموندلو، هغه شريعت چې خُدائ پاک موسىٰ له ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11175, '2 Chronicles 34:15', '2 Chronicles', 34, 15, '&nbsp;هغۀ سافن منشى ته وفرمائيل، ”ما دلته د مالِک خُدائ په کور کښې د شريعت کِتاب موندلے دے.“ هغۀ سافن له کِتاب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11176, '2 Chronicles 34:16', '2 Chronicles', 34, 16, '&nbsp;او سافن هغه کِتاب بادشاه له يوړو. سافن ورته ووئيل، ”تا چې د څۀ حُکم کړے وو نو مونږ هغه هر څۀ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11177, '2 Chronicles 34:17', '2 Chronicles', 34, 17, '&nbsp;کومې پېسې چې د مالِک خُدائ په کور کښې اېښودے شوې وې مونږ هغه کاريګرانو او د هغوئ مشرانو ته حواله کړې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11178, '2 Chronicles 34:18', '2 Chronicles', 34, 18, '&nbsp;بيا هغۀ ووئيل، ”هغه کِتاب دلته ما سره دے چې خِلقياه ما له راکړے دے.“ او هغۀ بادشاه ته د دې تلاوت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11179, '2 Chronicles 34:19', '2 Chronicles', 34, 19, '&nbsp;کله چې بادشاه هغه کِتاب واورېدو، نو هغۀ د خفګان نه خپلې جامې وشلولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11180, '2 Chronicles 34:20', '2 Chronicles', 34, 20, '&nbsp;او هغۀ خِلقياه، د سافن زوئ اخيقام، د ميکاياه زوئ عبدون، د دربار منشى سافن او د بادشاه مدد کوونکى عساياه له دا حُکم ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11181, '2 Chronicles 34:21', '2 Chronicles', 34, 21, '&nbsp;”لاړ شئ او د مالِک خُدائ سره زما او د هغه خلقو دپاره مشوره وکړئ چې هغوئ بيا هم په اِسرائيل او يهوداه کښې پاتې کيږى. د دې کِتاب تعليمات معلوم کړئ. مالِک خُدائ مونږ ته غصه دے ځکه چې زمونږ پلار نيکۀ د مالِک خُدائ کلام نۀ دے منلے او هغه کار يې نۀ دے کړے چې د کوم په حقله دا کِتاب فرمائى چې خامخا دې وکړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11182, '2 Chronicles 34:22', '2 Chronicles', 34, 22, '&nbsp;د بادشاه په حُکم، خِلقياه او نور لاړل چې د يوې ښځې سره مشوره وکړى چې نوم يې خُلده وو، دا پېغمبره د يروشلم په نوې حِصه کښې اوسېده. د هغې خاوند سلوم، د توقهت زوئ او د خسره نمسے وو، سلوم د مالِک خُدائ د کور د چُوغو مشر وو. چې څۀ شوى وُو نو هغوئ ورته هغه بيان وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11183, '2 Chronicles 34:23', '2 Chronicles', 34, 23, '&nbsp;او هغې ورته ووئيل چې واپس بادشاه له لاړ شئ او ورته ووايئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11184, '2 Chronicles 34:24', '2 Chronicles', 34, 24, '&nbsp;چې د مالِک خُدائ نه دا پېغام راغلے دے، ”زۀ به په يروشلم او د دې په ټولو خلقو افت راولم چې په کښې به هغه ټول لعنتونه وى چې په هغه کِتاب کښې ليکلے شوى دى کوم چې بادشاه ته بيان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11185, '2 Chronicles 34:25', '2 Chronicles', 34, 25, '&nbsp;هغوئ زۀ رد کړے يم او نورو معبودانو ته يې نذرانې پېش کړې دى او دوئ چې دا هر څۀ کړى دى د هغې په وجه يې زما غصه راپارولې ده. زما غصه د يروشلم خِلاف راوچته شوې ده او دا به کمه نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11186, '2 Chronicles 34:26', '2 Chronicles', 34, 26, '&nbsp;خو د يهوداه هغه بادشاه له واپس ورشه چا چې د مالِک خُدائ سره د مشورې دپاره رالېږلے يې او هغۀ ته ووايه چې، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د هغه پېغام په حقله داسې فرمائى چې تا اوس اوس واورېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11187, '2 Chronicles 34:27', '2 Chronicles', 34, 27, '&nbsp;نو تۀ پښېمانه شوې او د خُدائ پاک په حضور کښې دې خپل ځان عاجز کړو، کله چې تا واورېدل چې هغۀ د دې ځائ او خلقو خلاف خبرې وکړې. کله چې تا خپل ځان زما د وړاندې عاجز کړو او خپلې جامې دې وشلولې او زما په حضور کښې وژړل، نو ما ستا دعا واورېدله، مالِک خُدائ فرمائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11188, '2 Chronicles 34:28', '2 Chronicles', 34, 28, '&nbsp;او زۀ چې يروشلم له کومه سزا ورکوم هغه به تر هغه وخت پورې نۀ راځى چې ترڅو تۀ مړ شوے نۀ يې. او زۀ به تا پرېږدم چې په سلامتۍ سره مړ شې.“ نو هغه سړى د دې پېغام سره يوسياه بادشاه ته راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11189, '2 Chronicles 34:29', '2 Chronicles', 34, 29, '&nbsp;يوسياه بادشاه د يهوداه او يروشلم ټول مشران راغونډ کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11190, '2 Chronicles 34:30', '2 Chronicles', 34, 30, '&nbsp;او هغوئ په يو ځائ د مالِک خُدائ کور ته لاړل، چې اِمامان او ليويان او ټول خلق، مالداره او غريبانان په کښې شامل وُو. بادشاه د هغوئ ټولو په مخکښې د لوظ د هغه کِتاب تلاوت وکړو، کوم چې د مالِک خُدائ په کور کښې موندلے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11191, '2 Chronicles 34:31', '2 Chronicles', 34, 31, '&nbsp;هغه د شاهى ستنې سره ولاړ وو او د مالِک خُدائ سره يې يو لوظ وکړو چې د هغۀ تابعدارى به کوى او د زړۀ د اخلاصه د هغۀ قانون او حُکمونه به منى او هغه مطالبې به پوره کوى کومې چې د دې لوظ سره تړلې دى، هم هغه شان چې څنګه په هغه کِتاب کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11192, '2 Chronicles 34:32', '2 Chronicles', 34, 32, '&nbsp;هغۀ د بنيامين خلق او د يروشلم خلق هم هغه لوظ ته مجبور کړل. نو د يروشلم خلقو د لوظ هغه مطالبې ومنلې کوم لوظ چې هغوئ د خپل پلار نيکۀ خُدائ پاک سره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11193, '2 Chronicles 34:33', '2 Chronicles', 34, 33, '&nbsp;نو يوسياه بادشاه هغه ټول حرام کاره بُتان تباه کړل کوم چې د اِسرائيل په علاقه کښې وُو او چې ترڅو پورې هغه ژوندے وو، نو هغوئ د مالِک خُدائ د هغوئ د پلار نيکۀ خُدائ پاک نه نۀ اوړېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11194, '2 Chronicles 35:1', '2 Chronicles', 35, 1, '&nbsp;يوسياه بادشاه په يروشلم کښې د مالِک خُدائ د درناوى دپاره د فسحې اختر وکړو، د وړومبۍ مياشتې په څوارلسمه ورځ هغوئ د اختر دپاره ګډُورى حلال کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11195, '2 Chronicles 35:2', '2 Chronicles', 35, 2, '&nbsp;هغۀ اِمامانو ته هغه ذمه وارۍ حواله کړې کومې چې هغوئ د مالِک خُدائ په کور کښې کولې او د هغوئ حوصله افزائى يې وکړه چې دا په ښۀ طريقه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11196, '2 Chronicles 35:3', '2 Chronicles', 35, 3, '&nbsp;هغۀ د بنى اِسرائيلو اُستاذانو يعنې هغه ليويانو ته هم دا اصُول وښودل، چې هغوئ مالِک خُدائ ته وقف شوى وُو، ”د لوظ صندوق د مالِک خُدائ په هغه کور کښې کېږدئ کوم چې د داؤد زوئ سليمان بادشاه جوړ کړے دے. تاسو به نور دا يو ځائ نه بل ځائ ته نۀ وړۍ، خو تاسو به د مالِک خُدائ د خپل خُدائ پاک او د هغۀ د خلقو بنى اِسرائيلو خِدمت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11197, '2 Chronicles 35:4', '2 Chronicles', 35, 4, '&nbsp;د ډلو په مطابق او د هغه ذمه وارو په مطابق په خپلو ځايونو باندې تيار ودرېږئ، کومې چې درته داؤد بادشاه او د هغۀ زوئ سليمان بادشاه حواله کړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11198, '2 Chronicles 35:5', '2 Chronicles', 35, 5, '&nbsp;او خپلو ځانونو له داسې ترتيب ورکړئ چې تاسو موجود يئ نو چې د بنى اِسرائيلو د هر خاندان مدد وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11199, '2 Chronicles 35:6', '2 Chronicles', 35, 6, '&nbsp;تاسو به د فسحې د اختر ګډُورى او چېلى حلال کړئ. اوس خپل ځانونه پاک کړئ او د دې دپاره قربانۍ تيارې کړئ چې ستاسو بنى اِسرائيليان هغه اصُول ومنى کوم چې مالِک خُدائ د موسىٰ په ذريعه ښودلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11200, '2 Chronicles 35:7', '2 Chronicles', 35, 7, '&nbsp;د فسحې د اختر دپاره يوسياه بادشاه خلقو له د خپلو څاروو او رَمو نه دېرش زره ګډان، ګډُورى او د چېلو بچى او درې زره غوَيى ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');